# 7z on the formats besides 7z, run under 7-Zip 26.03 (the oracle: Scoop's 7z.exe on
# Windows) and under cash's builtin: gzip, bzip2, xz, zstd and lzma streams, and tars,
# kept here as hex (made by cash 1.8.0's gzip, bzip2 and xz from "hello stream\n" of
# 2026-10-07 08:00 UTC, and 3000 numbers in 4 KiB xz blocks; zstd's by cash 1.10's
# zstd, with and without its checksum; tars by cash 1.8.0's tar in GNU, ustar, pax and
# v7 formats, with a name too long for one header; zips by cash 1.8.0's zip (with
# Info-ZIP's extra fields, ZipCrypto, and MS-DOS times only, of 2026-10-06) and by
# 7-Zip (NTFS times, AES-256, bzip2, LZMA, Deflate64)). 7z_formats.out is 7-Zip's
# output.
#
# As in 7z_cases.sh, `z` turns 7-Zip's CRLF and `\` into LF and `/`. 7-Zip shows times
# in Windows' own zone: the fixtures' 08:00 UTC is 10:00 in Brussels, and the pax
# tar's other times are two hours later than UTC there too.
#
# Regenerate the golden file (on Windows, with Scoop's 7-Zip and a cash without the
# builtin, such as 1.9.0), then shift the Brussels times to UTC:
#   cash 7z_formats.sh | awk '{ s = $0; o = "";
#     while (match(s, /2026-10-07 [0-9][0-9]:/)) {
#       o = o substr(s, 1, RSTART + 10) sprintf("%02d", substr(s, RSTART + 11, 2) - 2) ":";
#       s = substr(s, RSTART + RLENGTH) }
#     print o s }' > 7z_formats.out

exec 2>&1 </dev/null
export TZ=UTC0
dir=$(mktemp -d)
cd "$dir" || exit 1
z() { 7z "$@" > "$dir/o.txt" 2>&1; r=$?; tr -d '\r' < "$dir/o.txt" | sed 's#\\#/#g'; echo "rc=$r"; }
unhex() { printf "$(printf '%s' "$1" | sed 's/../\\x&/g')"; }
unhex 1f8b080800fcc56a0003612e74787400cb48cdc9c957282e294a4dcce5020097f486bb0d000000 > a.txt.gz
unhex 425a6839314159265359746f435a000002d1800010400022469c0020002201a6408069a68c211149476f78bb9229c28483a37a1ad0 > a.txt.bz2
unhex fd377a585a000004e6d6b44604c0110d2101160000000000000000008888cd6801000c68656c6c6f2073747265616d0a000000004432b405aac6da0200012d0d79931d7e1fb6f37d010000000004595a > a.txt.xz
unhex 5d00008000ffffffffffffffff00341949ee8de916728c0b9ccbb8e907ec59fffe8be800 > a.txt.lzma
unhex 1f8b0800000000000003cb48cdc9c957282e294a4dcce5020097f486bb0d000000 > n.gz
unhex  > big.txt.xz
unhex 28b52ffd84380d00000069000068656c6c6f2073747265616d0a7bcf528b > a.txt.zst
unhex 28b52ffd80380d00000069000068656c6c6f2073747265616d0a > nc.zst
unhex  > gnu.tar
unhex  > ustar.tar
unhex  > posix.tar
unhex  > v7.tar
unhex  > i.zip
unhex  > s.zip
unhex  > e.zip
unhex  > aes.zip
unhex  > bz.zip
unhex  > lz.zip
unhex  > d64.zip
unhex 504b03040a00000000000050465db04d88e20400000004000000090000006f6c642f6f2e7478746f6c640a504b01021e000a00000000000050465db04d88e204000000040000000900000000000000010020000000000000006f6c642f6f2e747874504b05060000000001000100370000002b0000000000 > dos.zip

echo "== list"
for f in a.txt.gz a.txt.bz2 a.txt.xz a.txt.lzma n.gz big.txt.xz a.txt.zst nc.zst; do
  z l $f
  z l -slt $f
done

echo "== test"
for f in a.txt.gz a.txt.bz2 a.txt.xz a.txt.lzma n.gz big.txt.xz a.txt.zst nc.zst; do
  z t $f
done
z t -bb1 a.txt.gz

echo "== extract"
z x a.txt.gz -oout
stat -c '%Y %n' out/a.txt
z x a.txt.bz2 -obz
z e -so a.txt.xz
z e -so a.txt.lzma
z e -so a.txt.zst
z x n.gz -oout
z x big.txt.xz -oout
find out bz | sort
cat out/a.txt out/n bz/a.txt
wc -c < out/big.txt

echo "== names"
cp a.txt.gz noext
z l noext
cp a.txt.gz x.tgz
z l -ba x.tgz
cp a.txt.bz2 y.TBZ
z l -ba y.TBZ
cp a.txt.lzma l.bin
z l l.bin
z l -tlzma l.bin
z l -tgzip l.bin
cp a.txt.gz gz.7z
z l gz.7z
z t gz.7z

echo "== damaged"
cp a.txt.gz tail.gz
printf 'tailjunk' >> tail.gz
z t tail.gz
head -c 20 a.txt.gz > cut.gz
z t cut.gz
z l cut.gz
cp a.txt.gz crc.gz
printf 'X' | dd of=crc.gz bs=1 seek=33 conv=notrunc 2>/dev/null
z t crc.gz
cp a.txt.bz2 tail.bz2
printf 'tailjunk' >> tail.bz2
z t tail.bz2
cp a.txt.xz tail.xz
printf 'tailjunk' >> tail.xz
z l tail.xz
z t tail.xz
cat a.txt.gz a.txt.gz > two.gz
z l two.gz
z t two.gz
cat a.txt.bz2 a.txt.bz2 > two.bz2
z t two.bz2
z e -so two.gz
printf 'junk' > j.gz
z l j.gz
z t j.gz

echo "== tar"
for f in gnu.tar ustar.tar posix.tar v7.tar; do
  z l $f
  z l -slt $f
done
z t gnu.tar
z t -bb1 posix.tar
z x gnu.tar -otar
find tar | sort
cat tar/d/a.txt
z e -so ustar.tar d/sub/b.txt
z l -ba v7.tar
cp gnu.tar t.bin
z l -ba t.bin
head -c 3000 gnu.tar > cut.tar
z l cut.tar
z t cut.tar
head -c 1100 gnu.tar > short.tar
z t short.tar
cp gnu.tar bad.tar
printf 'XX' | dd of=bad.tar bs=1 seek=1100 conv=notrunc 2>/dev/null
z l bad.tar
z t bad.tar

echo "== zip"
for f in i.zip s.zip dos.zip; do
  z l $f
  z l -slt $f
done
for f in e.zip aes.zip bz.zip lz.zip d64.zip; do
  z l -slt -psecret $f | sed -n '/^----------$/,$p'
done
for f in i.zip s.zip bz.zip lz.zip d64.zip dos.zip; do
  z t $f
done
z t -psecret e.zip
z t -psecret aes.zip
z t -pwrong e.zip
z t -pwrong aes.zip
z e -so -psecret aes.zip
z x i.zip -ozip
find zip | sort
cat zip/d/a.txt
cp i.zip i.dat
z l -ba i.dat
cp i.zip crc.zip
printf 'Z' | dd of=crc.zip bs=1 seek=300 conv=notrunc 2>/dev/null
z t crc.zip

# Writing. Archives 7-Zip compresses differ from cash's in their bytes, so `zs` leaves
# out the sizes and `cksum` checks only what is stored: tars, and zips with -mtm- (whose
# MS-DOS time is then 1980's in any zone).
zs() { z "$@" | grep -vE '^(Archive size: |Physical Size = |Headers Size = )'; }
zp() { z l -slt "$@" | grep -E '^(Path|Folder|Size|Modified|Attributes|Mode|Method|Characteristics|Version|Host OS|Encrypted|CRC) = |^rc='; }
zt() { z t "$@" | grep -E '^(Everything is Ok|ERROR|Sub items Errors|Archives with Errors|rc=)'; }
mkdir -p wd/d/sub
cd wd || exit 1
printf 'alpha alpha alpha alpha alpha alpha\n' > d/a.txt
printf 'beta beta\n' > d/sub/b.txt
: > d/empty
printf 'ro\n' > d/ro.txt
printf 'e\n' > "d/caf$(printf '\303\251')"
printf 's\n' > "d/smile$(printf '\342\230\272')"
seq 1 3000 > big.txt
L=d/0123456789012345678901234567890123456789012345678901234567890123456789/abcdefghijklmnopqrstuvwxyz0123456789abcdefghijklmnop
mkdir -p "${L%/*}"
printf 'long\n' > "$L"
touch -d '2026-10-07 08:00:00' d/a.txt d/sub/b.txt d/empty d/ro.txt d/caf* d/smile* big.txt "$L" "${L%/*}" d/sub d
chmod a-w d/ro.txt

echo "== write: tar"
z a -bb1 x.tar d/a.txt d/sub d/empty d/ro.txt
cksum < x.tar
zp x.tar
z a -mm=pax p.tar d/sub "$L"
cksum < p.tar
z a g.tar "$L"
cksum < g.tar
z u -bb3 x.tar d/a.txt d/sub d/empty d/ro.txt
cksum < x.tar
z d -bb3 x.tar d/a.txt
cksum < x.tar
z rn x.tar d/sub d/moved
cksum < x.tar
z l -ba x.tar
touch -d '2026-10-07 09:00:00' d/sub/b.txt
z u -bb1 x.tar d/sub
touch -d '2026-10-07 08:00:00' d/sub/b.txt
z a -mtm- t0.tar d/a.txt
cksum < t0.tar
7z a -so -ttar sox d/sub > so.tar
echo "rc=$?"
cksum < so.tar
z a bad.tar d/a.txt -mx=x
z a bad2.tar d/a.txt -md=24
cp t0.tar t1.tar
z a t1.tar d/a.txt -md=24

echo "== write: gzip, bzip2, xz"
zs a x.gz d/a.txt
od -A n -t x1 -N 16 x.gz
zp x.gz | grep -v '^Packed'
zs a y.gz d
zs u x.gz d/a.txt
zs rn -bb3 x.gz a.txt b.txt
od -A n -t x1 -N 16 x.gz
zs a -mx9 x9.gz d/a.txt
od -A n -t x1 -N 10 x9.gz
zs a -mtm- t0.gz d/a.txt
od -A n -t x1 -N 10 t0.gz
zs a -mtc t1.gz d/a.txt
zs a -tgzip noext d/a.txt
ls noext*
zs a x.bz2 d/a.txt
zt x.bz2
zs a x.xz big.txt
z l -slt x.xz | grep -E '^(Method|Streams|Blocks) ='
zs a -mcrc=8 x64.xz d/a.txt
z l -slt x64.xz | grep -E '^Method ='
zs d x.xz x
cksum < x.xz
z a x.zst d/a.txt
cp x.gz q.tar
z a q.tar d/a.txt

echo "== write: zip"
z a -mx0 -mtm- -bb3 s.zip d/a.txt d/sub d/empty d/ro.txt
cksum < s.zip
zp s.zip
z a -mx0 -mtm- n.zip d/caf* d/smile*
cksum < n.zip
z l -slt n.zip | grep -E '^(Size|Method|Characteristics) ='
cp s.zip r.zip
z rn -mtm- -bb3 r.zip d/a.txt d/x.txt
cksum < r.zip
cp s.zip x.zip
z d -bb3 x.zip d/empty
cksum < x.zip
z u -mx0 -mtm- -bb3 x.zip d/a.txt d/empty
cksum < x.zip
zs a f.zip d/a.txt d/sub d/empty
zp f.zip | grep -v '^CRC'
zs a -mm=LZMA l.zip d/a.txt big.txt
zt l.zip
zp l.zip | grep -E '^(Path|Method|Version) ='
zs a -mm=PPMd pp.zip d/a.txt big.txt
zt pp.zip
zs a -mm=BZip2 b.zip big.txt
zt b.zip
zs a -mm=xz xz.zip big.txt
zt xz.zip
zp xz.zip | grep -E '^(Method|Version) ='
zs a -mx0 -pab c.zip d/a.txt
zt -pab c.zip
zp -pab c.zip | grep -E '^(Path|Method|Version|Encrypted) ='
zs a -pab -mem=AES256 e.zip d/a.txt big.txt
zt -pab e.zip
zs a -pab e.zip d/sub/b.txt
zp -pab e.zip | grep -E '^(Path|Method|Version|CRC) ='
z a -mm=zstd zs.zip d/a.txt
z a -mm=Deflate64x d64.zip d/a.txt
7z a -so -tzip -mx0 sox d/a.txt > so.zip
echo "rc=$?"

echo "== write: -si"
zs a -si s.gz < d/a.txt
zp s.gz | grep -v '^Packed'
zs a -sinamed.txt s2.gz < d/a.txt
z l -ba s2.gz | sed 's/  *[0-9]*  named/ named/'
printf 'piped\n' | zs a -si p.gz
z l -slt p.gz | grep -E '^(Path|Size) ='
z a -sinamed.txt s.tar < d/a.txt
cksum < s.tar
printf 'piped\n' | z a -sinamed.txt p.tar
zs a -sinamed.txt s.7z < d/a.txt
zp s.7z | grep -v '^Method'
printf 'piped\n' | zs a -si p.7z
z l -slt p.7z | grep -E '^(Path|Size) ='
z a -si -mx0 -mtm- s.zip < d/a.txt
cksum < s.zip
printf 'piped\n' | zs a -si -mx0 p.zip
z l -slt p.zip | grep -E '^(Path|Size|Method|Characteristics) ='
z a -si -mx0 -pab sc.zip < d/a.txt
zs a -si -mx0 -pab -mem=AES128 sa.zip < d/a.txt
zt -pab sa.zip

echo "== read: -si"
z l -si < ../a.txt.gz
z l -si -tzip < s.zip
z t -si -tzip < s.zip
z l -si -tgzip < ../a.txt.gz
z l -slt -si -tgzip < ../a.txt.gz
z t -si -tgzip < ../a.txt.gz
z e -si -tgzip -osi1 < ../a.txt.gz
ls si1
z l -sinamed.gz -tgzip < ../a.txt.gz
z l -si -tgzip < ../n.gz
z t -si -tgzip < x.tar
z l -slt -si -ttar < x.tar
z t -si -ttar < x.tar
z x -si -ttar -osi2 < s.tar
find si2 | sort
7z e -si -ttar -so named.txt < s.tar
for f in xz bz2 zst lzma; do
  t=$f
  case $f in bz2) t=bzip2;; zst) t=zstd;; esac
  z l -slt -si -t$t < ../a.txt.$f
  z t -si -t$t < ../a.txt.$f
done
